const body = $input.first().json.body || $input.first().json;
const query = $input.first().json.query || {};

const rawDate = (body.leaveDate || body.leave_date || '').trim();
const fmt = (d) => {
  if (!d) return '';
  const pd = new Date(d);
  if (isNaN(pd)) return d;
  return pd.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
};
return [{ json: {
  token: body.token || query.token || '',
  action: body.action || query.action || 'approve',
  employeeName: body.employeeName || body.employee_name || '',
  employeeEmail: body.employeeEmail || body.employee_email || '',
  leaveDate: rawDate,
    leaveDateDisplay: fmt(rawDate),
  endDateDisplay: fmt(body.end_date || body.endDate || ''),
  leaveDays: parseInt(body.leaveDays || body.leave_days || 0),
  leaveId: body.leaveId || '',
  reason: body.reason || '',
  department: body.department || '',
  backendUrl: '{{ $env.BACKEND_URL }}/api/approval/hr'
} }];

const resp = $input.first().json;
const data = resp.body || resp;
const input = $('Parse Input').first().json;

const rawDate = (input.leaveDate || '').trim();
const rawEndDate = input.end_date || input.endDate || '';
const endDateComputed = rawEndDate || (rawDate ? (() => {
  const d = new Date(rawDate); d.setDate(d.getDate() + (parseInt(input.leaveDays) || 1) - 1); return d.toISOString().split('T')[0];
})() : '');
const fmt = (d) => {
  if (!d) return '';
  const pd = new Date(d);
  if (isNaN(pd)) return d;
  return pd.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

return [{ json: {
  success: resp.statusCode === 200,
  status: data.status || '',
  message: data.message || '',
  leaveId: data.leaveId || input.leaveId || '',
  action: input.action,
  employeeName: input.employeeName,
  employeeEmail: input.employeeEmail,
  leaveDate: rawDate,
  leaveDateDisplay: fmt(rawDate),
  endDateDisplay: fmt(endDateComputed),
  leaveDays: input.leaveDays,
  reason: input.reason,
  department: input.department
} }];

