parameters.jsCode:
// Get prepared data from previous nodes
const prepNode = $('Prep: Email: HR Approved').first().json;
const tokenNode = $input.first().json;

const to = prepNode._to || '';
const subject = prepNode._subject || '';  
const htmlBody = prepNode._htmlBody || '';
const accessToken = tokenNode.accessToken || '';

// Build MIME message
const mimeLines = [
  'MIME-Version: 1.0',
  'Content-Type: text/html; charset=UTF-8',
  'To: ' + to,
  'Subject: =?UTF-8?B?' + Buffer.from(subject).toString('base64') + '?=',
  '',
  htmlBody
];

const raw = mimeLines.join('\r\n');

// Base64url encode
const encoded = Buffer.from(raw)
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/g, '');

return { json: { raw: encoded, accessToken, to, subject } };

